/// Help questions for one role (MASTER-5 Task 42). Order: en, hi, hinglish, kn, ta, te, mr, gu, bn, pa, ks, ur.
const Map<String, List<String>> faqRoleStrings = {
  'faqQ12': ['How do I make and share a bilty (LR)?', 'बिल्टी (LR) कैसे बनाऊँ और भेजूँ?', 'Bilty (LR) kaise banayein aur bhejein?', 'ಬಿಲ್ಟಿ (LR) ಹೇಗೆ ಮಾಡಿ ಹಂಚಿಕೊಳ್ಳುವುದು?', 'பில்டி (LR) எப்படி உருவாக்கி பகிர்வது?', 'బిల్టీ (LR) ఎలా చేసి పంచుకోవాలి?', 'बिल्टी (LR) कशी बनवावी आणि पाठवावी?', 'બિલ્ટી (LR) કેવી રીતે બનાવી મોકલવી?', 'বিল্টি (LR) কীভাবে বানিয়ে পাঠাবেন?', 'ਬਿਲਟੀ (LR) ਕਿਵੇਂ ਬਣਾਈਏ ਤੇ ਭੇਜੀਏ?', 'بِلٹی (LR) کیتھ بناوُن تہٕ شیئر کرُن؟', 'بلٹی (LR) کیسے بنائیں اور بھیجیں؟'],
  'faqA12': ['Open the trip and choose Bilty (LR), then Issue. Pick the copy (driver, consignee or full) and share it as a PDF or a link. Rates and phone numbers never go on the driver\'s copy.', 'ट्रिप खोलकर बिल्टी (LR) चुनें, फिर जारी करें। कॉपी (ड्राइवर, कंसाइनी या पूरी) चुनें और PDF या लिंक से भेजें। ड्राइवर की कॉपी पर दाम और फ़ोन नंबर कभी नहीं जाते।', 'Trip kholkar Bilty (LR) chunein, phir Issue karein. Copy (driver, consignee ya poori) chunein aur PDF ya link se bhejein. Driver ki copy par rate aur phone number kabhi nahi jaate.', 'ಟ್ರಿಪ್ ತೆರೆದು ಬಿಲ್ಟಿ (LR) ಆರಿಸಿ, ನಂತರ ನೀಡಿ. ಪ್ರತಿಯನ್ನು (ಚಾಲಕ, ಪಡೆಯುವವರು ಅಥವಾ ಪೂರ್ಣ) ಆರಿಸಿ ಮತ್ತು PDF ಅಥವಾ ಲಿಂಕ್ ಆಗಿ ಹಂಚಿಕೊಳ್ಳಿ. ಚಾಲಕರ ಪ್ರತಿಯಲ್ಲಿ ದರ ಮತ್ತು ಫೋನ್ ಸಂಖ್ಯೆ ಎಂದಿಗೂ ಇರುವುದಿಲ್ಲ.', 'பயணத்தைத் திறந்து பில்டி (LR) தேர்ந்து வழங்கவும். நகலை (ஓட்டுநர், பெறுநர் அல்லது முழு) தேர்ந்து PDF அல்லது இணைப்பாகப் பகிரவும். ஓட்டுநர் நகலில் விலையும் தொலைபேசி எண்ணும் ஒருபோதும் வராது.', 'ట్రిప్ తెరిచి బిల్టీ (LR) ఎంచుకుని జారీ చేయండి. కాపీ (డ్రైవర్, గ్రహీత లేదా పూర్తి) ఎంచుకుని PDF లేదా లింక్‌గా పంచుకోండి. డ్రైవర్ కాపీలో రేట్లు, ఫోన్ నంబర్లు ఎప్పుడూ ఉండవు.', 'ट्रिप उघडून बिल्टी (LR) निवडा, मग जारी करा. प्रत (ड्रायव्हर, प्राप्तकर्ता किंवा पूर्ण) निवडा आणि PDF किंवा लिंकने पाठवा. ड्रायव्हरच्या प्रतीवर दर आणि फोन नंबर कधीच जात नाहीत.', 'ટ્રિપ ખોલી બિલ્ટી (LR) પસંદ કરો, પછી જારી કરો. નકલ (ડ્રાઇવર, પ્રાપ્તકર્તા કે પૂરી) પસંદ કરી PDF કે લિંકથી મોકલો. ડ્રાઇવરની નકલ પર ભાવ અને ફોન નંબર ક્યારેય જતા નથી.', 'ট্রিপ খুলে বিল্টি (LR) বেছে ইস্যু করুন। কপি (ড্রাইভার, গ্রহীতা বা পূর্ণ) বেছে PDF বা লিংকে পাঠান। ড্রাইভারের কপিতে দর ও ফোন নম্বর কখনও যায় না।', 'ਟ੍ਰਿੱਪ ਖੋਲ੍ਹ ਕੇ ਬਿਲਟੀ (LR) ਚੁਣੋ, ਫਿਰ ਜਾਰੀ ਕਰੋ। ਕਾਪੀ (ਡਰਾਈਵਰ, ਪ੍ਰਾਪਤ ਕਰਤਾ ਜਾਂ ਪੂਰੀ) ਚੁਣੋ ਤੇ PDF ਜਾਂ ਲਿੰਕ ਨਾਲ ਭੇਜੋ। ਡਰਾਈਵਰ ਦੀ ਕਾਪੀ ਤੇ ਭਾਅ ਅਤੇ ਫ਼ੋਨ ਨੰਬਰ ਕਦੇ ਨਹੀਂ ਜਾਂਦੇ।', 'ٹرِپ کھولِو تہٕ بِلٹی (LR) ژارِو، پتہ جاری کرِو۔ کاپی (ڈرائیور، وصول کرنہٕ والۍ یا پوٗر) ژارِو تہٕ PDF یا لنکہٕ ذریعہ شیئر کرِو۔ ڈرائیور ہنز کاپی پیٹھ چھہ ریٹ تہٕ فون نمبر کتھ نہ گژھان۔', 'ٹرپ کھول کر بلٹی (LR) چنیں، پھر جاری کریں۔ کاپی (ڈرائیور، وصول کنندہ یا مکمل) چنیں اور PDF یا لنک سے بھیجیں۔ ڈرائیور کی کاپی پر ریٹ اور فون نمبر کبھی نہیں جاتے۔'],
  'faqQ13': ['What is inspection mode for the compliance details?', 'अनुपालन विवरण के लिए जाँच मोड क्या है?', 'Compliance details ke liye inspection mode kya hai?', 'ಅನುಸರಣೆ ವಿವರಗಳಿಗೆ ತಪಾಸಣೆ ಮೋಡ್ ಎಂದರೇನು?', 'இணக்க விவரங்களுக்கான ஆய்வு முறை என்ன?', 'కంప్లయన్స్ వివరాలకు ఇన్‌స్పెక్షన్ మోడ్ ఏమిటి?', 'अनुपालन तपशिलांसाठी तपासणी मोड म्हणजे काय?', 'અનુપાલન વિગતો માટે તપાસ મોડ શું છે?', 'কমপ্লায়েন্স তথ্যের জন্য পরিদর্শন মোড কী?', 'ਪਾਲਣਾ ਵੇਰਵਿਆਂ ਲਈ ਜਾਂਚ ਮੋਡ ਕੀ ਹੈ?', 'کمپلائنس تفصیلن خاطرٕ انسپیکشن موڈ کیا چھُ؟', 'تعمیل کی تفصیل کے لیے معائنہ موڈ کیا ہے؟'],
  'faqA13': ['On each bilty you choose whether the GST and goods-value details are hidden, shown, or shown only after you approve a driver\'s inspection request. An approval lasts 2 hours, can be given in advance for up to 72 hours, and every request and approval is recorded.', 'हर बिल्टी पर आप चुनते हैं कि GST और माल-मूल्य का विवरण छिपा, दिखे, या ड्राइवर की जाँच-माँग मंज़ूर करने के बाद ही दिखे। मंज़ूरी 2 घंटे चलती है, 72 घंटे तक पहले से दी जा सकती है, और हर माँग व मंज़ूरी दर्ज होती है।', 'Har bilty par aap chunte hain ki GST aur maal-value ki details chhupi rahein, dikhein, ya driver ki inspection request manzoor karne ke baad hi dikhein. Manzoori 2 ghante chalti hai, 72 ghante tak pehle se di ja sakti hai, aur har request aur manzoori record hoti hai.', 'ಪ್ರತಿ ಬಿಲ್ಟಿಯಲ್ಲಿ GST ಮತ್ತು ಸರಕು ಮೌಲ್ಯದ ವಿವರಗಳನ್ನು ಮರೆಮಾಡಬೇಕೇ, ತೋರಿಸಬೇಕೇ ಅಥವಾ ಚಾಲಕರ ತಪಾಸಣೆ ವಿನಂತಿಯನ್ನು ನೀವು ಒಪ್ಪಿದ ನಂತರ ಮಾತ್ರ ತೋರಿಸಬೇಕೇ ಎಂದು ಆರಿಸುತ್ತೀರಿ. ಒಪ್ಪಿಗೆ 2 ಗಂಟೆ ಇರುತ್ತದೆ, 72 ಗಂಟೆಗಳವರೆಗೆ ಮುಂಚಿತವಾಗಿ ನೀಡಬಹುದು, ಮತ್ತು ಪ್ರತಿ ವಿನಂತಿ ಹಾಗೂ ಒಪ್ಪಿಗೆ ದಾಖಲಾಗುತ್ತದೆ.', 'ஒவ்வொரு பில்டியிலும் GST, பொருள் மதிப்பு விவரங்களை மறைக்கவா, காட்டவா, அல்லது ஓட்டுநரின் ஆய்வுக் கோரிக்கையை நீங்கள் ஏற்ற பிறகே காட்டவா என்று தேர்வு செய்கிறீர்கள். ஒப்புதல் 2 மணி நேரம் நீடிக்கும், 72 மணி நேரம் வரை முன்கூட்டியே தரலாம், ஒவ்வொரு கோரிக்கையும் ஒப்புதலும் பதிவாகும்.', 'ప్రతి బిల్టీపై GST, సరుకు విలువ వివరాలను దాచాలా, చూపాలా, లేక డ్రైవర్ ఇన్‌స్పెక్షన్ అభ్యర్థనను మీరు ఆమోదించాకే చూపాలా అని ఎంచుకుంటారు. ఆమోదం 2 గంటలు ఉంటుంది, 72 గంటల వరకు ముందుగా ఇవ్వవచ్చు, ప్రతి అభ్యర్థన, ఆమోదం నమోదవుతాయి.', 'प्रत्येक बिल्टीवर GST आणि मालमूल्य तपशील लपवायचे, दाखवायचे, की ड्रायव्हरची तपासणी विनंती मंजूर केल्यावरच दाखवायचे हे तुम्ही ठरवता. मंजुरी 2 तास चालते, 72 तासांपर्यंत आधी देता येते, आणि प्रत्येक विनंती व मंजुरी नोंदली जाते.', 'દરેક બિલ્ટી પર GST અને માલ-મૂલ્યની વિગતો છુપાવવી, બતાવવી કે ડ્રાઇવરની તપાસ વિનંતી તમે મંજૂર કરો પછી જ બતાવવી તે તમે નક્કી કરો છો. મંજૂરી 2 કલાક ચાલે છે, 72 કલાક સુધી અગાઉથી આપી શકાય છે, અને દરેક વિનંતી તથા મંજૂરી નોંધાય છે.', 'প্রতিটি বিল্টিতে GST ও মালের মূল্যের তথ্য লুকানো, দেখানো, নাকি ড্রাইভারের পরিদর্শন অনুরোধ আপনি মঞ্জুর করার পরেই দেখানো — তা আপনি ঠিক করেন। অনুমোদন ২ ঘণ্টা চলে, ৭২ ঘণ্টা পর্যন্ত আগে থেকে দেওয়া যায়, এবং প্রতিটি অনুরোধ ও অনুমোদন নথিভুক্ত হয়।', 'ਹਰ ਬਿਲਟੀ ਤੇ GST ਅਤੇ ਮਾਲ-ਮੁੱਲ ਦੇ ਵੇਰਵੇ ਲੁਕਾਉਣੇ, ਦਿਖਾਉਣੇ ਜਾਂ ਡਰਾਈਵਰ ਦੀ ਜਾਂਚ ਬੇਨਤੀ ਮਨਜ਼ੂਰ ਕਰਨ ਮਗਰੋਂ ਹੀ ਦਿਖਾਉਣੇ, ਇਹ ਤੁਸੀਂ ਚੁਣਦੇ ਹੋ। ਮਨਜ਼ੂਰੀ 2 ਘੰਟੇ ਚੱਲਦੀ ਹੈ, 72 ਘੰਟੇ ਤੱਕ ਪਹਿਲਾਂ ਦਿੱਤੀ ਜਾ ਸਕਦੀ ਹੈ, ਅਤੇ ਹਰ ਬੇਨਤੀ ਤੇ ਮਨਜ਼ੂਰੀ ਦਰਜ ਹੁੰਦੀ ਹੈ।', 'ہر بِلٹی پیٹھ ژارِو توہہ کہ GST تہٕ مالکۍ قیمتکۍ تفصیل لُکراوُن، ظاہر کرُن یا ڈرائیور ہنز انسپیکشن درخواست منظور کرنہٕ پتہ ظاہر کرُن۔ منظوری چھ 2 گھنٹہٕ چلان، 72 گھنٹن تام پیشگی دِنہٕ ییہ ہکان، تہٕ ہر درخواست تہٕ منظوری چھ درج گژھان۔', 'ہر بلٹی پر آپ طے کرتے ہیں کہ GST اور مال کی قیمت کی تفصیل چھپی رہے، دکھائی دے، یا ڈرائیور کی معائنہ درخواست منظور کرنے کے بعد ہی دکھائی دے۔ منظوری 2 گھنٹے چلتی ہے، 72 گھنٹے تک پہلے سے دی جا سکتی ہے، اور ہر درخواست اور منظوری درج ہوتی ہے۔'],
  'faqQ14': ['How do I show the LR at a checkpoint?', 'चेकपोस्ट पर LR कैसे दिखाऊँ?', 'Checkpost par LR kaise dikhayein?', 'ಚೆಕ್‌ಪೋಸ್ಟ್‌ನಲ್ಲಿ LR ಹೇಗೆ ತೋರಿಸುವುದು?', 'சோதனைச் சாவடியில் LR ஐ எப்படிக் காட்டுவது?', 'చెక్‌పోస్ట్ వద్ద LR ఎలా చూపాలి?', 'चेकपोस्टवर LR कसे दाखवावे?', 'ચેકપોસ્ટ પર LR કેવી રીતે બતાવવી?', 'চেকপোস্টে LR কীভাবে দেখাবেন?', 'ਚੈੱਕਪੋਸਟ ਤੇ LR ਕਿਵੇਂ ਦਿਖਾਈਏ?', 'چیکپوسٹ پیٹھ LR کیتھ ہیرُن؟', 'چیک پوسٹ پر LR کیسے دکھائیں؟'],
  'faqA14': ['Open the trip and tap LR. If the owner hid the compliance details, tap Show inspection: the owner is asked, and once approved you can see them and save an offline Inspection copy that deletes itself when the approval ends. Rates stay hidden from you.', 'ट्रिप खोलकर LR दबाएँ। अगर मालिक ने अनुपालन विवरण छिपाए हैं तो जाँच के लिए दिखाएँ दबाएँ: मालिक से पूछा जाता है, मंज़ूरी मिलते ही आप उन्हें देख सकते हैं और ऑफ़लाइन जाँच-कॉपी सहेज सकते हैं, जो मंज़ूरी खत्म होते ही अपने आप हट जाती है। दाम आपसे छिपे रहते हैं।', 'Trip kholkar LR dabayein. Agar malik ne compliance details chhupayi hain to Show inspection dabayein: malik se poocha jaata hai, manzoori milte hi aap unhe dekh sakte hain aur offline Inspection copy save kar sakte hain, jo manzoori khatam hote hi apne aap hat jaati hai. Rate aapse chhupe rehte hain.', 'ಟ್ರಿಪ್ ತೆರೆದು LR ಒತ್ತಿ. ಮಾಲೀಕರು ಅನುಸರಣೆ ವಿವರಗಳನ್ನು ಮರೆಮಾಡಿದ್ದರೆ ತಪಾಸಣೆಗೆ ತೋರಿಸಿ ಒತ್ತಿ: ಮಾಲೀಕರನ್ನು ಕೇಳಲಾಗುತ್ತದೆ, ಒಪ್ಪಿದ ನಂತರ ನೀವು ನೋಡಬಹುದು ಮತ್ತು ಆಫ್‌ಲೈನ್ ತಪಾಸಣೆ ಪ್ರತಿಯನ್ನು ಉಳಿಸಬಹುದು; ಒಪ್ಪಿಗೆ ಮುಗಿದಾಗ ಅದು ತಾನಾಗಿ ಅಳಿಯುತ್ತದೆ. ದರಗಳು ನಿಮಗೆ ಮರೆಯಾಗಿರುತ್ತವೆ.', 'பயணத்தைத் திறந்து LR ஐத் தட்டவும். உரிமையாளர் இணக்க விவரங்களை மறைத்திருந்தால் ஆய்வுக்குக் காட்டு என்பதைத் தட்டவும்: உரிமையாளரிடம் கேட்கப்படும், ஒப்புதல் கிடைத்ததும் பார்க்கலாம்; ஆஃப்லைன் ஆய்வு நகலைச் சேமிக்கலாம், ஒப்புதல் முடிந்ததும் அது தானாக அழியும். விலைகள் உங்களுக்கு மறைந்திருக்கும்.', 'ట్రిప్ తెరిచి LR నొక్కండి. యజమాని కంప్లయన్స్ వివరాలను దాచి ఉంటే ఇన్‌స్పెక్షన్ కోసం చూపు నొక్కండి: యజమానిని అడుగుతారు, ఆమోదం రాగానే మీరు చూడవచ్చు, ఆఫ్‌లైన్ ఇన్‌స్పెక్షన్ కాపీని సేవ్ చేయవచ్చు; ఆమోదం ముగియగానే అది తనంతట తానే తొలగిపోతుంది. రేట్లు మీకు దాచబడతాయి.', 'ट्रिप उघडून LR दाबा. मालकाने अनुपालन तपशील लपवले असतील तर तपासणीसाठी दाखवा दाबा: मालकाला विचारले जाते, मंजुरी मिळताच तुम्ही ते पाहू शकता आणि ऑफलाइन तपासणी प्रत जतन करू शकता, जी मंजुरी संपताच आपोआप हटते. दर तुमच्यापासून लपलेले राहतात.', 'ટ્રિપ ખોલી LR દબાવો. માલિકે અનુપાલન વિગતો છુપાવી હોય તો તપાસ માટે બતાવો દબાવો: માલિકને પૂછવામાં આવે છે, મંજૂરી મળતાં તમે જોઈ શકો અને ઑફલાઇન તપાસ નકલ સાચવી શકો, જે મંજૂરી પૂરી થતાં આપોઆપ ભૂંસાય છે. ભાવ તમારાથી છુપાયેલા રહે છે.', 'ট্রিপ খুলে LR চাপুন। মালিক কমপ্লায়েন্স তথ্য লুকিয়ে রাখলে পরিদর্শনের জন্য দেখান চাপুন: মালিককে জিজ্ঞাসা করা হয়, অনুমোদন মিললে আপনি দেখতে পারেন ও অফলাইন পরিদর্শন কপি সংরক্ষণ করতে পারেন, যা অনুমোদন শেষ হলে নিজে থেকে মুছে যায়। দর আপনার কাছে লুকানো থাকে।', 'ਟ੍ਰਿੱਪ ਖੋਲ੍ਹ ਕੇ LR ਦਬਾਓ। ਜੇ ਮਾਲਕ ਨੇ ਪਾਲਣਾ ਵੇਰਵੇ ਲੁਕਾਏ ਹੋਣ ਤਾਂ ਜਾਂਚ ਲਈ ਦਿਖਾਓ ਦਬਾਓ: ਮਾਲਕ ਤੋਂ ਪੁੱਛਿਆ ਜਾਂਦਾ ਹੈ, ਮਨਜ਼ੂਰੀ ਮਿਲਦਿਆਂ ਤੁਸੀਂ ਵੇਖ ਸਕਦੇ ਹੋ ਅਤੇ ਔਫਲਾਈਨ ਜਾਂਚ ਕਾਪੀ ਸੰਭਾਲ ਸਕਦੇ ਹੋ, ਜੋ ਮਨਜ਼ੂਰੀ ਮੁੱਕਣ ਤੇ ਆਪਣੇ ਆਪ ਮਿਟ ਜਾਂਦੀ ਹੈ। ਭਾਅ ਤੁਹਾਥੋਂ ਲੁਕੇ ਰਹਿੰਦੇ ਹਨ।', 'ٹرِپ کھولِو تہٕ LR دَبِو۔ اگر مالکن چھہ تعمیل تفصیل لُکراومت تیلہِ انسپیکشن خاطرٕ ظاہر کرِو دَبِو: مالکہٕ چھہ پرژھان، منظوری کِنۍ پتہ ہکو توہہ وُچھُن تہٕ آف لائن انسپیکشن کاپی محفوظ کٔرتھ، یۅس منظوری ختم گژھنہٕ پتہ پانے مٹان چھ۔ ریٹ چھہ توہہِ پیٹھ لُکراومت۔', 'ٹرپ کھول کر LR دبائیں۔ اگر مالک نے تعمیل کی تفصیل چھپائی ہو تو معائنے کے لیے دکھائیں دبائیں: مالک سے پوچھا جاتا ہے، منظوری ملتے ہی آپ دیکھ سکتے ہیں اور آف لائن معائنہ کاپی محفوظ کر سکتے ہیں، جو منظوری ختم ہونے پر خود مٹ جاتی ہے۔ ریٹ آپ سے چھپے رہتے ہیں۔'],
  'faqQ15': ['How are my earnings and commission shown?', 'मेरी कमाई और कमीशन कैसे दिखते हैं?', 'Meri kamai aur commission kaise dikhte hain?', 'ನನ್ನ ಗಳಿಕೆ ಮತ್ತು ಕಮಿಷನ್ ಹೇಗೆ ತೋರಿಸಲಾಗುತ್ತದೆ?', 'என் வருமானமும் கமிஷனும் எப்படிக் காட்டப்படுகின்றன?', 'నా ఆదాయం, కమీషన్ ఎలా చూపిస్తారు?', 'माझी कमाई आणि कमिशन कसे दिसते?', 'મારી કમાણી અને કમિશન કેવી રીતે દેખાય છે?', 'আমার আয় ও কমিশন কীভাবে দেখানো হয়?', 'ਮੇਰੀ ਕਮਾਈ ਅਤੇ ਕਮਿਸ਼ਨ ਕਿਵੇਂ ਦਿਖਦੇ ਹਨ?', 'میون کمٲے تہٕ کمیشن کیتھ ہیکھ ظاہر گژھان؟', 'میری کمائی اور کمیشن کیسے دکھائے جاتے ہیں؟'],
  'faqA15': ['The Wallet shows what is pending, available and paid out, and each trip\'s earning and commission. Tap Earnings statement to share a month, a financial year or everything as CSV or PDF. These are records kept by {app}; no money moves through the app.', 'वॉलेट में बाकी, उपलब्ध और चुकाई गई रकम, और हर ट्रिप की कमाई व कमीशन दिखते हैं। कमाई का विवरण दबाकर महीना, वित्त वर्ष या सब कुछ CSV या PDF में भेजें। ये {app} के रिकॉर्ड हैं; ऐप से पैसा नहीं चलता।', 'Wallet mein pending, available aur paid-out rakam, aur har trip ki kamai aur commission dikhte hain. Earnings statement dabakar mahina, financial year ya sab kuch CSV ya PDF mein bhejein. Yeh {app} ke record hain; app se paisa nahi chalta.', 'ವ್ಯಾಲೆಟ್ ಬಾಕಿ, ಲಭ್ಯ ಮತ್ತು ಪಾವತಿಸಿದ ಮೊತ್ತ ಹಾಗೂ ಪ್ರತಿ ಟ್ರಿಪ್‌ನ ಗಳಿಕೆ ಮತ್ತು ಕಮಿಷನ್ ತೋರಿಸುತ್ತದೆ. ಗಳಿಕೆಯ ವಿವರ ಒತ್ತಿ ತಿಂಗಳು, ಆರ್ಥಿಕ ವರ್ಷ ಅಥವಾ ಎಲ್ಲವನ್ನೂ CSV ಅಥವಾ PDF ಆಗಿ ಹಂಚಿಕೊಳ್ಳಿ. ಇವು {app} ಇಟ್ಟ ದಾಖಲೆಗಳು; ಆ್ಯಪ್ ಮೂಲಕ ಹಣ ಹೋಗುವುದಿಲ್ಲ.', 'வாலெட் நிலுவை, கிடைக்கும், செலுத்தப்பட்ட தொகையையும் ஒவ்வொரு பயணத்தின் வருமானம், கமிஷனையும் காட்டும். வருமான அறிக்கையைத் தட்டி மாதம், நிதியாண்டு அல்லது அனைத்தையும் CSV அல்லது PDF ஆகப் பகிரவும். இவை {app} வைத்திருக்கும் பதிவுகள்; செயலியில் பணம் நகராது.', 'వాలెట్ పెండింగ్, అందుబాటులో, చెల్లించిన మొత్తాన్ని, ప్రతి ట్రిప్ ఆదాయం, కమీషన్‌ను చూపిస్తుంది. ఆదాయ వివరణ నొక్కి నెల, ఆర్థిక సంవత్సరం లేదా అన్నింటినీ CSV లేదా PDF గా పంచుకోండి. ఇవి {app} ఉంచే రికార్డులు; యాప్ ద్వారా డబ్బు కదలదు.', 'वॉलेटमध्ये प्रलंबित, उपलब्ध आणि दिलेली रक्कम, तसेच प्रत्येक ट्रिपची कमाई व कमिशन दिसते. कमाईचे विवरण दाबून महिना, आर्थिक वर्ष किंवा सर्व काही CSV किंवा PDF मध्ये पाठवा. या {app} च्या नोंदी आहेत; अॅपमधून पैसे हलत नाहीत.', 'વૉલેટમાં બાકી, ઉપલબ્ધ અને ચૂકવેલી રકમ તથા દરેક ટ્રિપની કમાણી અને કમિશન દેખાય છે. કમાણીનું સ્ટેટમેન્ટ દબાવી મહિનો, નાણાકીય વર્ષ કે બધું CSV અથવા PDF માં મોકલો. આ {app} ના રેકોર્ડ છે; એપથી પૈસા ફરતા નથી.', 'ওয়ালেটে বাকি, উপলব্ধ ও পরিশোধিত অর্থ এবং প্রতিটি ট্রিপের আয় ও কমিশন দেখা যায়। আয়ের বিবরণী চেপে মাস, অর্থবছর বা সবকিছু CSV বা PDF-এ পাঠান। এগুলি {app}-র রেকর্ড; অ্যাপের মাধ্যমে টাকা চলাচল করে না।', 'ਵਾਲਿਟ ਵਿੱਚ ਬਕਾਇਆ, ਉਪਲਬਧ ਅਤੇ ਅਦਾ ਕੀਤੀ ਰਕਮ ਅਤੇ ਹਰ ਟ੍ਰਿੱਪ ਦੀ ਕਮਾਈ ਤੇ ਕਮਿਸ਼ਨ ਦਿਖਦਾ ਹੈ। ਕਮਾਈ ਦਾ ਵੇਰਵਾ ਦਬਾ ਕੇ ਮਹੀਨਾ, ਵਿੱਤੀ ਸਾਲ ਜਾਂ ਸਭ ਕੁਝ CSV ਜਾਂ PDF ਵਿੱਚ ਭੇਜੋ। ਇਹ {app} ਦੇ ਰਿਕਾਰਡ ਹਨ; ਐਪ ਰਾਹੀਂ ਪੈਸੇ ਨਹੀਂ ਚੱਲਦੇ।', 'والیٹ چھُ باقی، دستیاب تہٕ ادا کرمُت رقم تہٕ ہر ٹرپکۍ کمٲے تہٕ کمیشن ظاہر کران۔ کمٲے ہند بیان دَبِو تہٕ مہینہ، مالی ؤری یا سارے CSV یا PDF منز شیئر کرِو۔ یہ چھہ {app} ہندۍ ریکارڈ؛ ایپس ذریعہ چھہ نہ پیسہ چلان۔', 'والیٹ میں باقی، دستیاب اور ادا شدہ رقم اور ہر ٹرپ کی کمائی اور کمیشن دکھائے جاتے ہیں۔ کمائی کا گوشوارہ دبا کر مہینہ، مالی سال یا سب کچھ CSV یا PDF میں بھیجیں۔ یہ {app} کے ریکارڈ ہیں؛ ایپ سے پیسہ نہیں چلتا۔'],
  'faqQ16': ['How do I assign a vehicle and driver to a trip?', 'ट्रिप के लिए वाहन और ड्राइवर कैसे तय करूँ?', 'Trip ke liye gaadi aur driver kaise assign karein?', 'ಟ್ರಿಪ್‌ಗೆ ವಾಹನ ಮತ್ತು ಚಾಲಕರನ್ನು ಹೇಗೆ ನಿಯೋಜಿಸುವುದು?', 'பயணத்துக்கு வாகனம், ஓட்டுநரை எப்படி நியமிப்பது?', 'ట్రిప్‌కు వాహనం, డ్రైవర్‌ను ఎలా కేటాయించాలి?', 'ट्रिपसाठी वाहन आणि ड्रायव्हर कसे नेमावे?', 'ટ્રિપ માટે વાહન અને ડ્રાઇવર કેવી રીતે નક્કી કરવા?', 'ট্রিপে গাড়ি ও ড্রাইভার কীভাবে ঠিক করবেন?', 'ਟ੍ਰਿੱਪ ਲਈ ਵਾਹਨ ਅਤੇ ਡਰਾਈਵਰ ਕਿਵੇਂ ਤੈਅ ਕਰੀਏ?', 'ٹرپس خاطرٕ گاڈۍ تہٕ ڈرائیور کیتھ مقرر کرُن؟', 'ٹرپ کے لیے گاڑی اور ڈرائیور کیسے مقرر کریں؟'],
  'faqA16': ['Open Trips, pick the trip and choose Assign, then a vehicle and an active driver of your company. The driver then runs the trip on their own phone with the OTP steps. You can change the assignment until pickup.', 'ट्रिप खोलें, ट्रिप चुनें और तय करें दबाएँ, फिर अपनी कंपनी का वाहन और सक्रिय ड्राइवर चुनें। फिर ड्राइवर अपने फ़ोन पर OTP चरणों से ट्रिप चलाता है। पिकअप तक आप बदल सकते हैं।', 'Trips kholein, trip chunein aur Assign dabayein, phir apni company ki gaadi aur active driver chunein. Phir driver apne phone par OTP steps se trip chalata hai. Pickup tak aap badal sakte hain.', 'ಟ್ರಿಪ್‌ಗಳನ್ನು ತೆರೆದು ಟ್ರಿಪ್ ಆರಿಸಿ, ನಿಯೋಜಿಸಿ ಒತ್ತಿ, ನಂತರ ನಿಮ್ಮ ಕಂಪನಿಯ ವಾಹನ ಮತ್ತು ಸಕ್ರಿಯ ಚಾಲಕರನ್ನು ಆರಿಸಿ. ಚಾಲಕರು ತಮ್ಮ ಫೋನ್‌ನಲ್ಲಿ OTP ಹಂತಗಳೊಂದಿಗೆ ಟ್ರಿಪ್ ನಡೆಸುತ್ತಾರೆ. ಪಿಕಪ್‌ವರೆಗೆ ಬದಲಾಯಿಸಬಹುದು.', 'பயணங்களைத் திறந்து பயணத்தைத் தேர்ந்து நியமி என்பதைத் தட்டி, உங்கள் நிறுவன வாகனத்தையும் செயலில் உள்ள ஓட்டுநரையும் தேர்ந்தெடுக்கவும். ஓட்டுநர் தன் தொலைபேசியில் OTP படிகளுடன் பயணத்தை நடத்துவார். ஏற்றும் வரை மாற்றலாம்.', 'ట్రిప్పులు తెరిచి ట్రిప్ ఎంచుకుని కేటాయించు నొక్కి, మీ కంపెనీ వాహనం, యాక్టివ్ డ్రైవర్‌ను ఎంచుకోండి. డ్రైవర్ తన ఫోన్‌లో OTP దశలతో ట్రిప్ నడుపుతారు. పికప్ వరకు మార్చవచ్చు.', 'ट्रिप उघडा, ट्रिप निवडा आणि नेमा दाबा, मग तुमच्या कंपनीचे वाहन आणि सक्रिय ड्रायव्हर निवडा. ड्रायव्हर स्वतःच्या फोनवर OTP टप्प्यांसह ट्रिप चालवतो. पिकअपपर्यंत बदलता येते.', 'ટ્રિપ ખોલો, ટ્રિપ પસંદ કરી નક્કી કરો દબાવો, પછી તમારી કંપનીનું વાહન અને સક્રિય ડ્રાઇવર પસંદ કરો. ડ્રાઇવર પોતાના ફોન પર OTP પગલાંથી ટ્રિપ ચલાવે છે. પિકઅપ સુધી બદલી શકાય છે.', 'ট্রিপ খুলুন, ট্রিপ বেছে ঠিক করুন চাপুন, তারপর আপনার কোম্পানির গাড়ি ও সক্রিয় ড্রাইভার বেছে নিন। ড্রাইভার নিজের ফোনে OTP ধাপে ট্রিপ চালান। পিকআপ পর্যন্ত বদলানো যায়।', 'ਟ੍ਰਿੱਪ ਖੋਲ੍ਹੋ, ਟ੍ਰਿੱਪ ਚੁਣੋ ਤੇ ਤੈਅ ਕਰੋ ਦਬਾਓ, ਫਿਰ ਆਪਣੀ ਕੰਪਨੀ ਦਾ ਵਾਹਨ ਅਤੇ ਸਰਗਰਮ ਡਰਾਈਵਰ ਚੁਣੋ। ਡਰਾਈਵਰ ਆਪਣੇ ਫ਼ੋਨ ਤੇ OTP ਕਦਮਾਂ ਨਾਲ ਟ੍ਰਿੱਪ ਚਲਾਉਂਦਾ ਹੈ। ਪਿਕਅੱਪ ਤੱਕ ਬਦਲ ਸਕਦੇ ਹੋ।', 'ٹرپس کھولِو، ٹرِپ ژارِو تہٕ مقرر کرِو دَبِو، پتہ پنُن کمپنی ہنز گاڈۍ تہٕ سرگرم ڈرائیور ژارِو۔ ڈرائیور چھُ پنُن فونس پیٹھ OTP قدمن سیتۍ ٹرِپ چلان۔ پِکَپ تام ہیکو بدلاوُن۔', 'ٹرپس کھولیں، ٹرپ چنیں اور مقرر کریں دبائیں، پھر اپنی کمپنی کی گاڑی اور فعال ڈرائیور چنیں۔ ڈرائیور اپنے فون پر OTP کے مراحل سے ٹرپ چلاتا ہے۔ پک اپ تک بدل سکتے ہیں۔'],
  'faqQ17': ['How do I send a party its statement?', 'पार्टी को उसका विवरण कैसे भेजूँ?', 'Party ko uska statement kaise bhejein?', 'ಪಕ್ಷಕ್ಕೆ ಅದರ ವಿವರವನ್ನು ಹೇಗೆ ಕಳುಹಿಸುವುದು?', 'தரப்பினருக்கு அவர்களின் அறிக்கையை எப்படி அனுப்புவது?', 'పార్టీకి వారి వివరణను ఎలా పంపాలి?', 'पार्टीला तिचे विवरण कसे पाठवावे?', 'પાર્ટીને તેનું સ્ટેટમેન્ટ કેવી રીતે મોકલવું?', 'পক্ষকে তার বিবরণী কীভাবে পাঠাবেন?', 'ਪਾਰਟੀ ਨੂੰ ਉਸਦਾ ਵੇਰਵਾ ਕਿਵੇਂ ਭੇਜੀਏ?', 'پارٹی کس اوہس بیان کیتھ بھیجُن؟', 'پارٹی کو اس کا گوشوارہ کیسے بھیجیں؟'],
  'faqA17': ['Open Books, find the party and tap the share icon: you get a CSV or PDF of its trips, what it has paid and what is still due. Export all parties gives one line per party. These are statements of account, not tax invoices.', 'खाते खोलें, पार्टी ढूँढें और शेयर आइकन दबाएँ: उसकी ट्रिप, चुकाई रकम और बाकी रकम का CSV या PDF मिलता है। सभी पार्टियाँ निर्यात करने पर हर पार्टी की एक पंक्ति मिलती है। ये खाते का विवरण हैं, कर चालान नहीं।', 'Books kholein, party dhoondhein aur share icon dabayein: uski trips, chukai rakam aur baaki rakam ka CSV ya PDF milta hai. Saari parties export karne par har party ki ek line milti hai. Yeh account statement hain, tax invoice nahi.', 'ಲೆಕ್ಕಗಳನ್ನು ತೆರೆದು ಪಕ್ಷವನ್ನು ಹುಡುಕಿ ಹಂಚಿಕೆ ಐಕಾನ್ ಒತ್ತಿ: ಅದರ ಟ್ರಿಪ್‌ಗಳು, ಪಾವತಿಸಿದ ಮತ್ತು ಬಾಕಿ ಮೊತ್ತದ CSV ಅಥವಾ PDF ಸಿಗುತ್ತದೆ. ಎಲ್ಲ ಪಕ್ಷಗಳನ್ನು ರಫ್ತು ಮಾಡಿದರೆ ಪ್ರತಿ ಪಕ್ಷಕ್ಕೆ ಒಂದು ಸಾಲು. ಇವು ಖಾತೆ ವಿವರಗಳು, ತೆರಿಗೆ ಇನ್‌ವಾಯ್ಸ್ ಅಲ್ಲ.', 'கணக்குகளைத் திறந்து தரப்பினரைக் கண்டுபிடித்துப் பகிர்வு ஐகானைத் தட்டவும்: அவர்களின் பயணங்கள், செலுத்தியது, நிலுவை ஆகியவற்றின் CSV அல்லது PDF கிடைக்கும். அனைத்து தரப்பினரையும் ஏற்றுமதி செய்தால் ஒவ்வொருவருக்கும் ஒரு வரி. இவை கணக்கு அறிக்கைகள், வரி விலைப்பட்டியல் அல்ல.', 'ఖాతాలు తెరిచి పార్టీని కనుగొని షేర్ ఐకాన్ నొక్కండి: వారి ట్రిప్పులు, చెల్లించినది, ఇంకా బాకీ ఉన్నదాని CSV లేదా PDF వస్తుంది. అన్ని పార్టీలను ఎగుమతి చేస్తే ప్రతి పార్టీకి ఒక వరుస. ఇవి ఖాతా వివరణలు, పన్ను ఇన్వాయిస్‌లు కావు.', 'खाती उघडा, पार्टी शोधा आणि शेअर आयकॉन दाबा: तिच्या ट्रिप, दिलेली रक्कम आणि बाकी रक्कम यांचा CSV किंवा PDF मिळतो. सर्व पार्ट्या निर्यात केल्यास प्रत्येक पार्टीची एक ओळ मिळते. हे खात्याचे विवरण आहे, कर बीजक नाही.', 'ખાતાં ખોલો, પાર્ટી શોધો અને શેર આઇકન દબાવો: તેની ટ્રિપ, ચૂકવેલી અને બાકી રકમનો CSV અથવા PDF મળે છે. બધી પાર્ટીઓ નિકાસ કરવાથી દરેક પાર્ટીની એક લાઇન મળે છે. આ ખાતાનું સ્ટેટમેન્ટ છે, કર ઇન્વૉઇસ નથી.', 'হিসাব খুলে পক্ষকে খুঁজে শেয়ার আইকন চাপুন: তার ট্রিপ, পরিশোধিত ও বাকি টাকার CSV বা PDF পাবেন। সব পক্ষ রপ্তানি করলে প্রতি পক্ষের এক লাইন। এগুলি হিসাবের বিবরণী, কর চালান নয়।', 'ਖਾਤੇ ਖੋਲ੍ਹੋ, ਪਾਰਟੀ ਲੱਭੋ ਤੇ ਸਾਂਝਾ ਆਈਕਨ ਦਬਾਓ: ਉਸਦੀਆਂ ਟ੍ਰਿੱਪਾਂ, ਅਦਾ ਕੀਤੀ ਤੇ ਬਾਕੀ ਰਕਮ ਦਾ CSV ਜਾਂ PDF ਮਿਲਦਾ ਹੈ। ਸਾਰੀਆਂ ਪਾਰਟੀਆਂ ਬਰਾਮਦ ਕਰਨ ਤੇ ਹਰ ਪਾਰਟੀ ਦੀ ਇੱਕ ਲਾਈਨ ਮਿਲਦੀ ਹੈ। ਇਹ ਖਾਤੇ ਦੇ ਵੇਰਵੇ ਹਨ, ਟੈਕਸ ਇਨਵੌਇਸ ਨਹੀਂ।', 'کھاتہٕ کھولِو، پارٹی ژارِو تہٕ شیئر آئکن دَبِو: اوہس ٹرپس، ادا کرمُت تہٕ باقی رقمچ CSV یا PDF چھہ میلان۔ سارٕ پارٹیز ایکسپورٹ کرنہٕ چھہ ہر پارٹیہٕ اکھ لیکھ۔ یہ چھہ کھاتہٕ بیان، ٹیکس انوائس چھہ نہ۔', 'کھاتے کھولیں، پارٹی ڈھونڈیں اور شیئر آئیکن دبائیں: اس کے ٹرپ، ادا شدہ اور باقی رقم کا CSV یا PDF ملتا ہے۔ تمام پارٹیاں برآمد کرنے پر ہر پارٹی کی ایک لائن ملتی ہے۔ یہ کھاتے کے گوشوارے ہیں، ٹیکس انوائس نہیں۔'],
  'faqQ18': ['Can I use a promo code or credits?', 'क्या मैं प्रोमो कोड या क्रेडिट इस्तेमाल कर सकता हूँ?', 'Kya main promo code ya credits use kar sakta hoon?', 'ನಾನು ಪ್ರೋಮೋ ಕೋಡ್ ಅಥವಾ ಕ್ರೆಡಿಟ್ ಬಳಸಬಹುದೇ?', 'நான் ப்ரோமோ குறியீடு அல்லது கிரெடிட் பயன்படுத்தலாமா?', 'నేను ప్రోమో కోడ్ లేదా క్రెడిట్స్ వాడవచ్చా?', 'मी प्रोमो कोड किंवा क्रेडिट वापरू शकतो का?', 'શું હું પ્રોમો કોડ કે ક્રેડિટ વાપરી શકું?', 'আমি কি প্রোমো কোড বা ক্রেডিট ব্যবহার করতে পারি?', 'ਕੀ ਮੈਂ ਪ੍ਰੋਮੋ ਕੋਡ ਜਾਂ ਕ੍ਰੈਡਿਟ ਵਰਤ ਸਕਦਾ ਹਾਂ?', 'کیا بوزُن پرومو کوڈ یا کریڈٹ استعمال کٔرتھ؟', 'کیا میں پرومو کوڈ یا کریڈٹ استعمال کر سکتا ہوں؟'],
  'faqA18': ['Offers are switched on by {app} only at times. When they are on, an Offers block shows on Post Load and in More for you on Home. When they are off you simply pay the quoted fare.', 'ऑफ़र {app} कभी-कभी ही चालू करता है। चालू होने पर लोड डालते समय ऑफ़र का हिस्सा और होम पर आपके लिए और में दिखता है। बंद होने पर आप बस बताया गया किराया देते हैं।', 'Offers {app} kabhi-kabhi hi chalu karta hai. Chalu hone par Post Load par Offers ka hissa aur Home par More for you mein dikhta hai. Band hone par aap bas bataya gaya kiraya dete hain.', 'ಆಫರ್‌ಗಳನ್ನು {app} ಕೆಲವೊಮ್ಮೆ ಮಾತ್ರ ಆನ್ ಮಾಡುತ್ತದೆ. ಆನ್ ಇದ್ದಾಗ ಲೋಡ್ ಪೋಸ್ಟ್ ಮಾಡುವಾಗ ಮತ್ತು ಮುಖಪುಟದ ನಿಮಗಾಗಿ ಹೆಚ್ಚುವರಿಯಲ್ಲಿ ಆಫರ್ ಭಾಗ ಕಾಣುತ್ತದೆ. ಆಫ್ ಇದ್ದಾಗ ನೀವು ಹೇಳಿದ ಬಾಡಿಗೆಯನ್ನು ಮಾತ್ರ ಪಾವತಿಸುತ್ತೀರಿ.', 'சலுகைகளை {app} சில நேரங்களில் மட்டுமே இயக்கும். இயக்கத்தில் இருக்கும்போது சுமை பதிவிடும்போதும் முகப்பின் உங்களுக்காக மேலும் பகுதியிலும் சலுகைப் பகுதி தெரியும். இல்லாதபோது கூறப்பட்ட வாடகையை மட்டும் செலுத்துவீர்கள்.', 'ఆఫర్లను {app} కొన్నిసార్లు మాత్రమే ఆన్ చేస్తుంది. ఆన్‌లో ఉన్నప్పుడు లోడ్ పోస్ట్ చేసేటప్పుడు, హోమ్‌లో మీ కోసం మరిన్నిలో ఆఫర్ల భాగం కనిపిస్తుంది. ఆఫ్‌లో ఉన్నప్పుడు చెప్పిన కిరాయి మాత్రమే చెల్లిస్తారు.', 'ऑफर {app} कधी कधीच चालू करते. चालू असताना लोड टाकताना आणि होमवरील तुमच्यासाठी अधिकमध्ये ऑफर विभाग दिसतो. बंद असताना तुम्ही फक्त सांगितलेले भाडे देता.', 'ઑફર {app} ક્યારેક જ ચાલુ કરે છે. ચાલુ હોય ત્યારે લોડ મૂકતી વખતે અને હોમ પર તમારા માટે વધુમાં ઑફર વિભાગ દેખાય છે. બંધ હોય ત્યારે તમે ફક્ત કહેલું ભાડું ચૂકવો છો.', 'অফার {app} কখনও কখনও চালু করে। চালু থাকলে লোড দেওয়ার সময় ও হোমে আপনার জন্য আরও-এর মধ্যে অফার অংশ দেখা যায়। বন্ধ থাকলে আপনি শুধু বলা ভাড়া দেন।', 'ਆਫ਼ਰ {app} ਕਦੇ-ਕਦੇ ਹੀ ਚਾਲੂ ਕਰਦਾ ਹੈ। ਚਾਲੂ ਹੋਣ ਤੇ ਲੋਡ ਪਾਉਣ ਵੇਲੇ ਅਤੇ ਹੋਮ ਤੇ ਤੁਹਾਡੇ ਲਈ ਹੋਰ ਵਿੱਚ ਆਫ਼ਰ ਦਾ ਹਿੱਸਾ ਦਿਖਦਾ ਹੈ। ਬੰਦ ਹੋਣ ਤੇ ਤੁਸੀਂ ਸਿਰਫ਼ ਦੱਸਿਆ ਕਿਰਾਇਆ ਦਿੰਦੇ ਹੋ।', 'آفر چھہ {app} صرف کنہِ کنہِ وَقتہٕ چالو کران۔ چالو آسنہٕ پیٹھ چھہ لوڈ ڈالنہٕ وَقتہٕ تہٕ ہومس پیٹھ توہہِ خاطرٕ مزید منز آفرچ حصہ ظاہر گژھان۔ بند آسنہٕ پیٹھ چھوو توہہ صرف ونمت کرایہ ادا کران۔', 'آفرز {app} صرف کبھی کبھی چالو کرتا ہے۔ چالو ہونے پر لوڈ ڈالتے وقت اور ہوم پر آپ کے لیے مزید میں آفر کا حصہ دکھائی دیتا ہے۔ بند ہونے پر آپ صرف بتایا گیا کرایہ دیتے ہیں۔'],
};
